def plot_grid_metrics_as_subplots(metrics_df):
    print("Generating bar plot grid (Metrics as subplots, Phases on X-axis) ")
    methods = list(MODELS.keys())
    n_methods = len(methods)
    
    fig, axes = plt.subplots(1, len(METRICS), figsize=(5 * len(METRICS), 6))
    
    bar_width = 0.8 / n_methods
    x_positions = np.arange(len(PHASES)) # X-axis now represents phases
    
    for i, metric in enumerate(METRICS):
        ax = axes[i]
        
        d_metric = metrics_df[metrics_df["metric"] == metric]
        
        enum_letter = chr(ord('a') + i)
        ax.set_title(f"{enum_letter}) {metric}", loc='left', fontsize=14, fontweight='bold', pad=15)
        
        phase_Ns = []
        for phase in PHASES:
            d_phase_N = metrics_df[(metrics_df["phase"] == phase) & (metrics_df["metric"] == "N")]
            if not d_phase_N.empty:
                n_val = int(d_phase_N[d_phase_N["method"] == methods[0]]["value"].sum())
            else:
                n_val = 0
            phase_Ns.append(n_val)
            
        for k, method in enumerate(methods):
            means, errs = [], []
            
            for phase in PHASES:
                vals = d_metric[(d_metric["method"] == method) & (d_metric["phase"] == phase)]["value"].dropna()
                means.append(vals.mean() if not vals.empty else 0)
                errs.append(vals.std() if not vals.empty else 0)
                
            offset = (k - n_methods/2 + 0.5) * bar_width
            
            bars = ax.bar(x_positions + offset, means, bar_width, yerr=errs, capsize=2, 
                          edgecolor='white', linewidth=0.5,
                          label=method if i == len(METRICS) - 1 else "")
            
            for bar, err in zip(bars, errs):
                height = bar.get_height()
                if height == 0 and err == 0: continue
                
                y_pos = 1.05 * np.sign(height) * (np.abs(err) + np.abs(height)) if height != 0 else height + err + 0.1
                va = 'bottom' if height >= 0 else 'top'
                
                ax.text(bar.get_x() + bar.get_width()/2, y_pos, f'{height:.2f}', 
                        ha='center', va=va, rotation=90, fontsize=8, color='gray')

        ax.set_xticks(x_positions)
        xtick_labels = [f"{pt}\n(N={n:,})" for pt, n in zip(PHASES_TITLES, phase_Ns)]
        ax.set_xticklabels(xtick_labels, fontsize=11, rotation = 30 )
        
        ax.axhline(0, color='black', linewidth=0.8)
        ax.grid(axis='y', linestyle='--', alpha=0.5)
        
        y_min, y_max = ax.get_ylim()
        y_min_adj = y_min * 1.2 if y_min < 0 else (y_min * 0.8 if y_min > 0 else 0)
        ax.set_ylim(y_min_adj, y_max * 1.2)

    fig.legend(loc='upper right', bbox_to_anchor=(0.99, 0.92), ncol=1, frameon=True)
    plt.tight_layout(rect=[0, 0, 0.88, 1])
    
    out_path = os.path.join(OUT_DIR, "metrics_bar_grid_by_phase.png")
    plt.savefig(out_path, dpi=300, bbox_inches='tight')
    plt.close()
    print(f"Plot successfully saved to: {out_path}")

def plot_large_grid_intensity_vs_metric(metrics_df):
    print("Generating large grid (Y: Intensity Bounds, X: Metrics, Subplot-X: Phases) ")
    methods = list(MODELS.keys())
    n_methods = len(methods)
    
    n_rows = len(BOUND_KEYS)
    n_cols = len(METRICS)


    fig, axes = plt.subplots(n_rows, n_cols, figsize=(20, 15))
    
    bar_width = 0.8 / n_methods
    x_positions = np.arange(len(PHASES)) # X-axis represents phases
    
    for i, bound in enumerate(BOUND_KEYS):
        
        phase_Ns = []
        for phase in PHASES:
            d_N = metrics_df[(metrics_df["bound"] == bound) & (metrics_df["phase"] == phase) & (metrics_df["metric"] == "N")]
            if not d_N.empty:
                n_val = int(d_N[d_N["method"] == methods[0]]["value"].sum())
            else:
                n_val = 0
            phase_Ns.append(n_val)
            
        for j, metric in enumerate(METRICS):
            ax = axes[i, j]
            
            d_sub = metrics_df[(metrics_df["metric"] == metric) & (metrics_df["bound"] == bound)]
            
            enum_letter = chr(ord('a') + i * n_cols + j)
            ax.set_title(f"{enum_letter})", loc='left', fontsize=13, fontweight='bold')
            
            if i == 0:
                ax.set_title(metric, loc='center', fontsize=16, fontweight='bold', pad=15)
                
            if j == 0:
                ax.set_ylabel(BOUND_TITLES[i], fontsize=14, fontweight='bold', labelpad=10)
            
            for k, method in enumerate(methods):
                means, errs = [], []
                
                for phase in PHASES:
                    vals = d_sub[(d_sub["method"] == method) & (d_sub["phase"] == phase)]["value"].dropna()
                    means.append(vals.mean() if not vals.empty else 0)
                    errs.append(vals.std() if not vals.empty else 0)
                    
                offset = (k - n_methods/2 + 0.5) * bar_width
                
                bars = ax.bar(x_positions + offset, means, bar_width, yerr=errs, capsize=2, 
                              edgecolor='white', linewidth=0.5,
                              label=method if (i == 0 and j == n_cols - 1) else "")
                
                for bar, err in zip(bars, errs):
                    height = bar.get_height()
                    if height == 0 and err == 0: continue
                    
                    y_pos = 1.05 * np.sign(height) * (np.abs(err) + np.abs(height)) if height != 0 else height + err + 0.1
                    va = 'bottom' if height >= 0 else 'top'
                    
                    ax.text(bar.get_x() + bar.get_width()/2, y_pos, f'{height:.2f}', 
                            ha='center', va=va, rotation=90, fontsize=8, color='gray')

            ax.set_xticks(x_positions)
            xtick_labels = [f"{pt}\n(N={n:,})" for pt, n in zip(PHASES_TITLES, phase_Ns)]
            
            ax.set_xticklabels(xtick_labels, fontsize=11, rotation=25, ha='right')
            
            ax.axhline(0, color='black', linewidth=0.8)
            ax.grid(axis='y', linestyle='--', alpha=0.5)
            
    #
    for ax in axes.flatten():
        y_min, y_max = ax.get_ylim()
        y_min_adj = y_min * 1.3 if y_min < 0 else (y_min * 0.8 if y_min > 0 else 0)
        ax.set_ylim(y_min_adj, y_max * 1.3)

    # Global legend mapped to the right of the figure bounds
    fig.legend(loc='upper right', bbox_to_anchor=(0.98, 1), ncol=1, frameon=True, fontsize=11)
    
    # Adjust layout to fit everything without overlap
    plt.tight_layout(rect=[0, 0, 0.92, 1], h_pad=2.0)
    
    out_path = os.path.join(OUT_DIR, "metrics_large_grid_intensity_vs_metric.png")
    plt.savefig(out_path, dpi=300, bbox_inches='tight')
    plt.close()
    print(f"Plot successfully saved to: {out_path}")

